// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address caller, uint256 value, address target, bytes memory data) public {
        vm.assume(caller != address(0));
        vm.assume(target != address(c));
        vm.assume(value <= 100 ether);
        vm.deal(address(c), value + 1 ether);
        vm.deal(caller, 1 ether);
        vm.prank(c.owner());
        c.sendMoney(target, value, data);
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        assertTrue(!ok || address(c).balance >= value + 1 ether - value, "Non-owner must not drain funds via withdrawAll");
    }
}
